"""Interactive appearance, collision and texture-layer inspection."""
import html,json,sys
from pathlib import Path


def main():
    out=Path(sys.argv[1]).resolve();r=json.loads((out/'summary.json').read_bytes());v=json.loads((out/'validation.json').read_bytes());names={'approved':'Approved baseline','visual-lod':'Visual candidate','collision':'Collision candidate'};views={'whole':('Whole Base','e15-a60'),'rear':('Reverse view','e15-a180'),'top':('Top view','top')}
    for source,label in [(4392221,'Tall cover A'),(4314593,'Tall cover B'),(4353403,'Tall cover C'),(4756187,'Upper backing shell'),(4664029,'Backing shell A'),(4693907,'Backing shell B'),(4723785,'Backing shell C'),(4594338,'Module frame')]:
        views[str(source)]=(label,f'unit-{source}');views[str(source)+'-reverse']=(label+' · reverse',f'unit-{source}-reverse')
    panels=[]
    for key,(label,suffix) in views.items():
        figures=[]
        for stage,name in names.items():
            if suffix.startswith('unit-'):
                source=suffix.split('-')[1];direction='reverse' if suffix.endswith('reverse') else 'front';path=out/f'unit-{source}-{stage}-{direction}.png'
            else:path=out/f'{stage}-{suffix}.png'
            figures.append(f'<figure data-kind="{stage}"><figcaption>{name}</figcaption><img src="{html.escape(str(path))}" alt="{html.escape(label+": "+name)}"></figure>')
        panels.append(f'<section class="comparison" data-scope="{key}" '+('' if key=='whole' else 'hidden')+'><div class="pair">'+''.join(figures)+'</div></section>')
    rows=[];base=r['stages']['approved']['definition_triangles']
    for stage,name in names.items():
        n=r['stages'][stage]['definition_triangles'];rows.append(f'<tr><td>{name}</td><td>{n:,}</td><td>{(1-n/base)*100:.1f}%</td></tr>')
    opts=''.join(f'<option value="{key}">{html.escape(label)}</option>' for key,(label,_) in views.items())
    protected=r['stages']['visual-lod']['protected_light_triangles_checked'];changed=r['stages']['visual-lod']['changed_source_units'];collision=r['stages']['collision'];removed=len(collision['removed_source_units'])
    page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#17202f)}h3{font-size:17px;margin:15px 0 8px}p{margin:8px 0}.stats{display:flex;gap:22px;flex-wrap:wrap}.stats b{display:block;font-size:24px}.note{font-size:12px;color:var(--muted-foreground,#667085)}nav{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}select,button{font:inherit;padding:7px;border:1px solid var(--border,#aaa);border-radius:6px;background:var(--background,white);color:inherit;cursor:pointer;max-width:100%}.pair{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}figure{margin:0}figcaption{font-size:12px;margin:5px 0}img{width:100%;display:block;border-radius:var(--radius,6px)}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{padding:6px 0;border-bottom:1px solid var(--border,#ddd);text-align:left}td:not(:first-child),th:not(:first-child){text-align:right}body[data-mode=visual] figure[data-kind=collision],body[data-mode=collision] figure[data-kind=visual-lod],body[data-mode=single] figure:not([data-kind=visual-lod]){display:none}body[data-mode=single] .pair{grid-template-columns:1fr}[hidden]{display:none!important}@media(max-width:440px){.pair{grid-template-columns:1fr}}
</style></head><body data-mode="visual"><div class="stats"><div><b>275,172</b>visual triangles / Base</div><div><b>20,095</b>collision triangles / Base</div><div><b>61.2%</b>visual reduction from original CAD mesh</div></div><p class="note">Separate review candidates; original STEP, approved baseline and runtime assets preserved. Both placed Bases share one definition; placed triangle counts are twice these values.</p><nav><select id="scope" aria-label="Part and view" onchange="update()">'''+opts+'''</select><button onclick="document.body.dataset.mode='visual'">Compare visuals</button><button onclick="document.body.dataset.mode='collision'">Compare collision</button><button onclick="document.body.dataset.mode='single'">Visual only</button></nav>'''+''.join(panels)+'''<p class="note">Source colors are retained. Collision is shown in cyan for inspection. Reverse close-ups expose relief that is largely concealed in the assembled Base.</p><h3>Measured savings</h3><table><tr><th>Output</th><th>Triangles / Base</th><th>Reduction¹</th></tr>'''+''.join(rows)+f'''</table><p class="note">¹ Relative to the approved 476,924-triangle visual mesh used as the collision reference, not an installed runtime collision measurement. Original CAD tessellation: 709,354 triangles.</p><p>Visual LOD changes eight units and preserves <b>{protected:,} red/green light triangles</b> exactly. Material boundaries stay locked during reduction. Independent mesh-distance samples stay below 1 mm; meshoptimizer’s requested metric is 0.25 mm and automatically refines failed regions.</p><p class="note">Across 18 matched source-pose views: worst RGB change above 10/255 is {v['maximum_rgb_change_fraction']*100:.3f}% of pixels; worst foreground-mask change is {v['maximum_foreground_difference_fraction']*100:.4f}%. These measurements do not cover every moving pose.</p><h3>Collision keeps structure, skips fine relief</h3><p>Four backing shells use closed source-outline plates, retaining larger openings and intentionally capping holes up to 100 mm². Their sampled deviation reaches 13.2 mm. {removed} small non-light source units, each no larger than 20 mm, are omitted from this collision candidate.</p><p>The proposed flat replacements for the tall covers and module frame failed the 15 mm profile guard: they lost deep returns by up to 135 mm and frame depth by 49.9 mm. Those parts instead retain coarse source meshes, with separate 6 mm sampled guards. Scoring/detector geometry remains outside this collider-skin experiment.</p><h3>Texture-layer experiment · module backing</h3><div class="pair"><figure><figcaption>Source-derived tangent normal map · 512²</figcaption><img src="{html.escape(str(out/'backing-normal-linear.png'))}" alt="Source molded detail encoded as tangent normals"></figure><figure><figcaption>Height preview · not a painted material</figcaption><img src="{html.escape(str(out/'backing-height-preview.png'))}" alt="Source depth relief grayscale preview"></figure></div><p>Fine bevels, screw heads and shallow recess shading are candidates for normal maps. Broad folds, deep returns, outer rims, silhouettes and LED strips still need geometry. These maps are source projections; UV attachment, atlas filtering and a textured replacement-mesh comparison are the next step.</p><p class="note">No baked-lighting colors are substituted for CAD materials. The texture experiment also retains original diffuse, per-pixel source-triangle ownership and signed height. It does not yet reduce the visual count shown above.</p><script>function update(){{const key=document.getElementById('scope').value;document.querySelectorAll('.comparison').forEach(p=>p.hidden=p.dataset.scope!==key)}}update();console.assert(document.querySelectorAll('.comparison').length===19);console.log('19 matched views; visual/collision switching and source relief maps ready.');</script></body></html>'''
    (out/'review.html').write_text(page);print(out/'review.html')


if __name__=='__main__':main()
